<script setup lang="ts">
import { computed, ref, watch } from 'vue';
import type { PositionBlueprintView, PositionCompetitionView, TeamSummary } from '@torneos/shared';
import SportTabs from './SportTabs.vue';
import Icon from './Icon.vue';

const props = defineProps<{ view:PositionBlueprintView; competition:PositionCompetitionView|null; entries:TeamSummary[]; canManage:boolean; organizationId:string; categoryId:string; tournamentId:string; csrfToken:string }>();
const emit = defineEmits<{refresh:[]}>();
const tab=ref('fechas'),selectedRound=ref('F1'),selectedDay=ref(1),stageTab=ref('groups'),drawTab=ref('positions'),openSlot=ref(''),saving=ref(false),error=ref(''),openingCodes=ref<string[]>([]);
const groups=['F1','F2','F3','F4','F5','Cuartos','Cuadrangular 1','Cuadrangular 2','Cuadrangular 3'];
const slots=computed(()=>new Map(props.view.slots.map(slot=>[slot.slot_code,slot])));
const activeEntries=computed(()=>props.entries.filter(entry=>entry.category_id===props.categoryId&&entry.status==='active'));
const opening=computed(()=>props.view.games.filter(game=>game.sporting_round==='F1'));
const openingDone=computed(()=>opening.value.filter(game=>game.jornada_no===props.view.blueprint?.opening_first_jornada).map(game=>game.code));
watch(()=>props.view.blueprint?.revision,()=>{openingCodes.value=[...openingDone.value];error.value='';},{immediate:true});
const dayGroups=computed(()=>Array.from({length:14},(_,index)=>({jornada:index+1,games:props.view.games.filter(game=>game.jornada_no===index+1)})));
const roundGames=computed(()=>props.view.games.filter(game=>game.sporting_round===selectedRound.value));
const dayGames=computed(()=>props.view.games.filter(game=>game.jornada_no===selectedDay.value));
const nearbyDays=computed(()=>{const following=dayGroups.value.filter(day=>day.jornada>selectedDay.value&&day.games.length).slice(0,selectedDay.value>=10?2:1);return following.length?following:dayGroups.value.filter(day=>day.jornada===selectedDay.value-1&&day.games.length);});
const selectedDayDate=computed(()=>dayGames.value[0]?.planned_date || (selectedDay.value===1?props.view.blueprint?.opening_first_date:selectedDay.value===2?props.view.blueprint?.opening_second_date:null) || null);
const pendingOpening=computed(()=>opening.value.filter(game=>game.jornada_no===null));
const groupSlots=computed(()=>({A:props.view.slots.filter(slot=>slot.slot_code.startsWith('A')),B:props.view.slots.filter(slot=>slot.slot_code.startsWith('B'))}));
const stageGames=computed(()=>props.view.games.filter(game=>stageTab.value==='quarterfinals'?game.stage==='quarterfinal':game.stage==='quadrangular'));
function dateLabel(date:string|null){if(!date)return 'Por sortear';const [year,month,day]=date.split('-');return `${day}/${month}/${year}`;}
function roundName(round:string){return round.startsWith('Cuadrangular ')?`Final ${round.slice(-1)}`:round;}
function slotName(refCode:string){const slot=slots.value.get(refCode);if(slot)return slot.team_name||refCode;if(/^[1-4][AB]$/.test(refCode))return `${refCode[0]}.º Grupo ${refCode[1]}`;if(/^S[1-4]$/.test(refCode))return `${refCode[1]}.º entre los ganadores`;return refCode;}
function stageName(refCode:string){if(/^[1-4][AB]$/.test(refCode))return `${refCode[0]}.º Grupo ${refCode[1]}`;if(/^S[1-4]$/.test(refCode))return `${refCode[1]}.º ganador mejor ubicado`;return slotName(refCode);}
function stageLabel(game:PositionBlueprintView['games'][number]){return game.stage==='quarterfinal'?`Llave ${game.code.slice(2)}`:roundName(game.sporting_round);}
function centerPill(event:Event){(event.currentTarget as HTMLElement).scrollIntoView({behavior:'smooth',block:'nearest',inline:'center'});}
function badgeRef(refCode:string){return /^[AB][1-5]$/.test(refCode)?refCode[0]:refCode;}
function teamFor(refCode:string){const slot=slots.value.get(refCode);return slot?.entry_id?activeEntries.value.find(entry=>entry.entry_id===slot.entry_id)||null:null;}
function shield(refCode:string){const team=teamFor(refCode);return team?.has_shield?`/api/v1/organizations/${props.organizationId}/teams/${team.id}/shield`:null;}
function toggleOpening(code:string){openingCodes.value=openingCodes.value.includes(code)?openingCodes.value.filter(item=>item!==code):openingCodes.value.length<2?[...openingCodes.value,code]:[openingCodes.value[1],code];}
async function patch(path:string,payload:object){saving.value=true;error.value='';try{const response=await fetch(`/api/v1/organizations/${props.organizationId}/categories/${props.categoryId}/fixture/blueprint${path}`,{method:'PATCH',credentials:'same-origin',headers:{'Content-Type':'application/json','X-CSRF-Token':props.csrfToken},body:JSON.stringify(payload)});const result=await response.json();if(!response.ok)throw new Error(result.message||'No se pudo guardar.');emit('refresh');}catch(cause){error.value=cause instanceof Error?cause.message:'No se pudo guardar.';}finally{saving.value=false;}}
async function assign(slotCode:string,entryId:string|null){await patch(`/slots/${slotCode}`,{entryId});if(!error.value)openSlot.value='';}
async function saveOpening(){if(openingCodes.value.length!==2)return;await patch('/opening',{firstJornadaCodes:openingCodes.value});}
async function clearOpening(){await patch('/opening',{firstJornadaCodes:[]});}
const availableForSlot=computed(()=>activeEntries.value);
const assignedCount=computed(()=>props.view.slots.filter(slot=>slot.entry_id).length);
const canEditDraw=computed(()=>props.canManage&&!props.competition?.preparedMatches);
const results=computed(()=>new Map((props.competition?.results||[]).map(result=>[result.code,result])));
const matches=computed(()=>new Map((props.competition?.matches||[]).map(match=>[match.code,match])));
const drawCurrent=computed(()=>!!props.view.blueprint?.published_revision&&props.view.blueprint.published_revision===props.view.blueprint.revision);
const stageHasPublishedMatch=computed(()=>drawCurrent.value&&stageGames.value.some(game=>matches.value.get(game.code)?.day_status==='published'));
const championReady=computed(()=>{
  const state=props.competition;if(!drawCurrent.value||state?.competition.official.quadrangular!==6)return false;
  if(state.titleExtra?.decision==='extra')return state.titleExtra.dayStatus==='published'&&!!state.titleExtra.winnerEntryId;
  const first=state.competition.final?.groups[0];
  return !!first&&!first.unresolved&&first.teamIds.length===1&&(state.titleTie.length===1||state.titleExtra?.decision==='no_extra');
});
function gameName(game:PositionBlueprintView['games'][number],side:'home'|'away'){
  const id=props.competition?.competition.participants[game.code]?.[side==='home'?'homeEntryId':'awayEntryId'];
  return activeEntries.value.find(entry=>entry.entry_id===id)?.name||slotName(side==='home'?game.home_ref:game.away_ref);
}
function gameShield(game:PositionBlueprintView['games'][number],side:'home'|'away'){
  const id=props.competition?.competition.participants[game.code]?.[side==='home'?'homeEntryId':'awayEntryId'];
  const entry=activeEntries.value.find(item=>item.entry_id===id);
  return entry?.has_shield?`/api/v1/organizations/${props.organizationId}/teams/${entry.id}/shield`:null;
}
async function prepareMatches(){saving.value=true;error.value='';try{const response=await fetch(`/api/v1/organizations/${props.organizationId}/categories/${props.categoryId}/fixture/blueprint/sync`,{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json','X-CSRF-Token':props.csrfToken},body:'{}'});const result=await response.json();if(!response.ok)throw new Error(result.message||'No se pudieron preparar los partidos.');emit('refresh');}catch(cause){error.value=cause instanceof Error?cause.message:'No se pudieron preparar los partidos.';}finally{saving.value=false;}}
async function publishDraw(){if(!props.view.blueprint)return;saving.value=true;error.value='';try{const response=await fetch(`/api/v1/organizations/${props.organizationId}/categories/${props.categoryId}/fixture/blueprint/publish-draw`,{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json','X-CSRF-Token':props.csrfToken},body:JSON.stringify({expectedRevision:props.view.blueprint.revision})});const result=await response.json();if(!response.ok)throw new Error(result.message||'No se pudo publicar el sorteo.');emit('refresh');}catch(cause){error.value=cause instanceof Error?cause.message:'No se pudo publicar el sorteo.';}finally{saving.value=false;}}
</script>

<template>
  <section class="position-fixture">
    <SportTabs v-model="tab" :tabs="[{key:'fechas',label:'Fechas',icon:'ball'},{key:'jornadas',label:'Jornadas',icon:'calendar'},{key:'etapas',label:'Etapas',icon:'trophy'},{key:'sorteo',label:'Sorteo',icon:'users'}]" id="fixture-posiciones" />
    <p v-if="error" class="position-error" role="alert">{{ error }}</p>
    <div v-if="tab==='fechas'" id="fixture-posiciones-fechas-panel" role="tabpanel" aria-labelledby="fixture-posiciones-fechas-tab">
      <div class="position-pills" role="group" aria-label="Fecha deportiva"><button v-for="round in groups" :key="round" type="button" :aria-pressed="selectedRound===round" @click="selectedRound=round;centerPill($event)">{{ round.startsWith('F')?round:roundName(round) }}</button></div>
      <section class="position-section"><h3>{{ selectedRound.startsWith('F') ? `Fecha ${selectedRound.slice(1)}` : roundName(selectedRound) }}</h3>
        <div v-for="game in roundGames" :key="game.code" class="position-game"><span class="position-when">{{ game.jornada_no ? `J${game.jornada_no}` : 'J1/J2' }}<small>{{ dateLabel(game.planned_date) }}</small></span><span class="position-side"><img v-if="gameShield(game,'home')" :src="gameShield(game,'home')!" alt=""><b v-else>{{ badgeRef(game.home_ref) }}</b><strong>{{ gameName(game,'home') }}</strong></span><span class="position-vs">{{ results.get(game.code)?`${results.get(game.code)!.homeGoals}:${results.get(game.code)!.awayGoals}`:'–' }}</span><span class="position-side away"><img v-if="gameShield(game,'away')" :src="gameShield(game,'away')!" alt=""><b v-else>{{ badgeRef(game.away_ref) }}</b><strong>{{ gameName(game,'away') }}</strong></span><a v-if="matches.get(game.code)" class="position-match-link" :href="`#/partido/${categoryId}/${matches.get(game.code)!.match_id}`" :aria-label="`Abrir partido ${game.code}`">Abrir ›</a></div>
      </section>
      <p v-if="selectedRound==='Cuadrangular 3'&&view.blueprint?.extra_reserved_date" class="position-extra">{{ dateLabel(view.blueprint.extra_reserved_date) }} · Partido extra solo si se decide ante empate por el título.</p>
    </div>
    <div v-else-if="tab==='jornadas'" id="fixture-posiciones-jornadas-panel" role="tabpanel" aria-labelledby="fixture-posiciones-jornadas-tab">
      <div class="position-pills" role="group" aria-label="Jornada programada"><button v-for="day in dayGroups" :key="day.jornada" type="button" :aria-pressed="selectedDay===day.jornada" @click="selectedDay=day.jornada;centerPill($event)">J{{ day.jornada }}</button></div>
      <section class="position-section"><h3>Jornada {{ selectedDay }} <small>{{ dateLabel(selectedDayDate) }}</small></h3><div v-if="selectedDay<=2&&pendingOpening.length" class="position-hint">Los cinco partidos de F1 esperan el reparto de apertura.</div><div v-for="game in dayGames.length?dayGames:selectedDay<=2?pendingOpening:[]" :key="game.code" class="position-day-game"><small>{{ roundName(game.sporting_round) }}</small><strong>{{ slotName(game.home_ref) }} – {{ slotName(game.away_ref) }}</strong></div><template v-if="selectedDay>=3&&dayGames.length"><button v-for="nearby in nearbyDays" :key="nearby.jornada" type="button" class="position-adjacent" @click="selectedDay=nearby.jornada"><span>J{{ nearby.jornada }} · {{ dateLabel(nearby.games[0]?.planned_date||null) }}</span><strong v-for="game in nearby.games" :key="game.code">{{ gameName(game,'home') }} – {{ gameName(game,'away') }}</strong><Icon name="arrow" /></button></template></section>
    </div>
    <div v-else-if="tab==='etapas'" id="fixture-posiciones-etapas-panel" role="tabpanel" aria-labelledby="fixture-posiciones-etapas-tab">
      <div class="position-pills" role="group" aria-label="Etapa"><button type="button" :aria-pressed="stageTab==='groups'" @click="stageTab='groups';centerPill($event)">Grupos</button><button type="button" :aria-pressed="stageTab==='quarterfinals'" @click="stageTab='quarterfinals';centerPill($event)">Cuartos</button><button type="button" :aria-pressed="stageTab==='quadrangular'" @click="stageTab='quadrangular';centerPill($event)">Finales</button><button type="button" :aria-pressed="stageTab==='general'" @click="stageTab='general';centerPill($event)">Tabla general</button></div>
      <template v-if="stageTab==='groups'"><section v-for="(teams,group) in groupSlots" :key="group" class="position-section"><h3>Grupo {{ group }}</h3><div v-for="slot in teams" :key="slot.slot_code" class="position-stage-row"><b>{{ slot.slot_code }}</b><strong>{{ slot.team_name||'Por sortear' }}</strong></div></section></template>
      <section v-else-if="stageTab==='general'" class="position-section"><h3>Tabla general · primera etapa</h3><p class="position-hint">Se calcula con ambos grupos y los interseriales después de los partidos oficiales.</p></section>
      <section v-else class="position-section"><div class="position-stage-actions"><h3>{{ stageTab==='quarterfinals'?'Cuartos de final':'Finales' }}</h3><a v-if="canManage&&stageHasPublishedMatch" :href="`#/flyers/${tournamentId}/${stageTab==='quarterfinals'?'bracket':'final'}/${categoryId}`"><Icon name="file" />Flyer</a></div><p v-if="stageTab==='quadrangular'" class="position-hint">Solo los cuatro ganadores de cuartos; entre ellos, el orden viene de la tabla general de la primera etapa.</p><div v-for="game in stageGames" :key="game.code" class="position-stage-match"><div class="position-stage-meta"><span>{{ stageLabel(game) }}</span><small>J{{ game.jornada_no }} · {{ dateLabel(game.planned_date) }}</small></div><div class="position-stage-sides"><strong>{{ gameName(game,'home') }}</strong><em>{{ results.get(game.code)?`${results.get(game.code)!.homeGoals}:${results.get(game.code)!.awayGoals}`:'vs' }}</em><strong>{{ gameName(game,'away') }}</strong></div><a v-if="matches.get(game.code)" class="position-match-link" :href="`#/partido/${categoryId}/${matches.get(game.code)!.match_id}`">Abrir partido ›</a></div><a v-if="canManage&&stageTab==='quadrangular'&&championReady" class="position-champion-flyer" :href="`#/flyers/${tournamentId}/champion/${categoryId}`"><Icon name="trophy" />Flyer del campeón</a></section>
    </div>
    <div v-else id="fixture-posiciones-sorteo-panel" role="tabpanel" aria-labelledby="fixture-posiciones-sorteo-tab">
      <div class="position-pills" role="group" aria-label="Sorteo"><button type="button" :aria-pressed="drawTab==='positions'" @click="drawTab='positions'">Equipos</button><button type="button" :aria-pressed="drawTab==='opening'" @click="drawTab='opening'">Apertura</button></div>
      <section v-if="drawTab==='positions'" class="position-section"><h3>Posiciones de los equipos</h3>
        <div v-for="slot in view.slots" :key="slot.slot_code" class="position-slot"><button type="button" :disabled="!canEditDraw||saving" :aria-expanded="openSlot===slot.slot_code" @click="openSlot=openSlot===slot.slot_code?'':slot.slot_code"><b>{{ slot.slot_code }}</b><span>{{ slot.team_name||'Asignar equipo' }}</span><Icon name="chevron" /></button>
          <div v-if="openSlot===slot.slot_code && canManage" class="position-choices"><button v-if="slot.entry_id" type="button" :disabled="saving" @click="assign(slot.slot_code,null)">Quitar asignación</button><button v-for="entry in availableForSlot" :key="entry.entry_id" type="button" :disabled="saving||slot.entry_id===entry.entry_id" @click="assign(slot.slot_code,entry.entry_id)">{{ entry.name }}<small v-if="view.slots.some(item=>item.entry_id===entry.entry_id&&item.slot_code!==slot.slot_code)">Intercambiar</small></button></div>
        </div>
      </section>
      <section v-else-if="canManage" class="position-section"><h3>Apertura · J1 y J2</h3><p class="position-hint">Podés dejarla pendiente y publicar el sorteo de equipos. Elegí dos partidos para el 17/11; los otros tres irán al 19/11.</p><button v-for="game in opening" :key="game.code" type="button" class="position-opening" :aria-pressed="openingCodes.includes(game.code)" :disabled="saving||!canEditDraw" @click="toggleOpening(game.code)"><span>{{ openingCodes.includes(game.code)?'J1':openingCodes.length===2?'J2':'—' }}</span><strong>{{ slotName(game.home_ref) }} – {{ slotName(game.away_ref) }}</strong></button><button v-if="canEditDraw" type="button" class="position-save" :disabled="saving||openingCodes.length!==2||openingCodes.every(code=>openingDone.includes(code))&&openingDone.length===2" @click="saveOpening">Guardar reparto</button><button v-if="openingDone.length&&canEditDraw" type="button" class="position-reset" :disabled="saving" @click="clearOpening">Dejar pendiente</button></section>
      <div v-if="canManage" class="position-publish"><button type="button" :disabled="saving||view.blueprint?.published_revision===view.blueprint?.revision" @click="publishDraw">{{ view.blueprint?.published_revision?'Actualizar vista pública':'Publicar vista pública' }}</button><small v-if="assignedCount!==10">{{ assignedCount }}/10 puestos</small><a v-if="view.blueprint?.published_revision" :href="`/#/publico/${organizationId}/${tournamentId}`" target="_blank" rel="noopener">Ver como aficionado ↗</a></div>
      <div v-if="canManage&&competition?.rulesPublished" class="position-publish"><button type="button" :disabled="saving||assignedCount!==10||openingDone.length!==2||!!competition.preparedMatches" @click="prepareMatches">{{ competition.preparedMatches?'Partidos preparados':'Preparar partidos' }}</button><small v-if="!competition.preparedMatches&&openingDone.length!==2">Definí J1/J2 antes de preparar partidos.</small></div>
    </div>
  </section>
</template>

<style scoped>
.position-pills{display:flex;gap:4px;overflow-x:auto;scrollbar-width:none;border-bottom:1px solid #dce6e1}.position-pills::-webkit-scrollbar{display:none}.position-pills button{flex:none;min-height:42px;border:0;border-bottom:2px solid transparent;background:#fff;padding:0 11px;color:#577169;font:inherit;font-size:.74rem;font-weight:650}.position-pills button[aria-pressed=true]{border-bottom-color:#008a54;color:#075b40;font-weight:800}
.position-adjacent{position:relative;display:grid;gap:6px;width:100%;margin-top:15px;padding:10px 28px 10px 0;border:0;border-top:2px solid #dce6e1;background:#fff;color:#102329;text-align:left;font:inherit}.position-adjacent span{color:#176b4b;font-size:.7rem;font-weight:800}.position-adjacent strong{min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font-size:.72rem;font-weight:600}.position-adjacent .icon{position:absolute;right:2px;top:11px;width:16px;height:16px;color:#176b4b}.position-adjacent:focus-visible{outline:3px solid #008a54;outline-offset:2px}
.position-stage-row{display:grid;grid-template-columns:35px minmax(0,1fr) 18px;gap:8px;align-items:center;min-height:43px;border-top:1px solid #edf1ee;font-size:.77rem}.position-stage-row b{color:#086846}.position-stage-row strong{min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.position-stage-row span{text-align:right;color:#71827a}.position-stage-match{padding:9px 0 11px;border-top:1px solid #edf1ee}.position-stage-meta{display:flex;align-items:center;justify-content:space-between;gap:8px;color:#176b4b;font-size:.68rem;font-weight:800}.position-stage-meta small{color:#708278;font-size:.62rem;font-weight:500}.position-stage-sides{display:grid;grid-template-columns:minmax(0,1fr) 20px minmax(0,1fr);align-items:center;gap:8px;margin-top:7px}.position-stage-sides strong{min-width:0;font-size:.76rem;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.position-stage-sides strong:last-child{text-align:right}.position-stage-sides em{text-align:center;color:#6f8078;font-size:.62rem;font-style:normal;font-weight:600}
.position-fixture{background:#fff;max-width:880px;margin:0 auto;padding:0 16px 42px;color:#102329}.position-heading{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:12px 0}.position-heading h2{margin:0;font-size:1.15rem}.position-heading span{color:#60726c;font-size:.72rem}.position-section{border-top:1px solid #dce6e1;padding:13px 0 5px}.position-section h3{margin:0 0 8px;font-size:.85rem}.position-section h3 small{font-weight:500;color:#62746e;margin-left:8px}.position-game{display:grid;grid-template-columns:58px minmax(0,1fr) 12px minmax(0,1fr);gap:5px;align-items:center;min-height:61px;border-top:1px solid #edf1ee}.position-when{font-size:.68rem;font-weight:750;color:#276b51}.position-when small{display:block;font-size:.61rem;font-weight:500;color:#687b73}.position-side{display:flex;align-items:center;gap:5px;min-width:0}.position-side.away{flex-direction:row-reverse;text-align:right}.position-side img,.position-side b{flex:none;width:25px;height:25px;object-fit:contain;border-radius:50%;background:#e8efeb}.position-side b{display:grid;place-items:center;font-size:.58rem;color:#275640}.position-side strong{font-size:.69rem;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.position-vs{text-align:center;color:#7a8983}.position-day-game{display:grid;grid-template-columns:58px minmax(0,1fr);gap:9px;align-items:center;border-top:1px solid #edf1ee;min-height:44px}.position-day-game small{color:#267456;font-size:.68rem}.position-day-game strong{font-size:.76rem;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.position-slot{border-top:1px solid #e3ebe6}.position-slot>button{width:100%;display:flex;align-items:center;gap:10px;min-height:47px;border:0;background:#fff;color:inherit;text-align:left;font:inherit}.position-slot>button b{width:27px;color:#126b49}.position-slot>button span{flex:1;font-size:.8rem;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.position-slot>button .icon{width:16px;height:16px;color:#71827a}.position-choices{padding:3px 0 10px 35px;display:grid;grid-template-columns:1fr 1fr;gap:5px}.position-choices button{min-height:42px;padding:7px;border:1px solid #dce6e1;border-radius:5px;background:#f8faf9;text-align:left;font:inherit;font-size:.72rem}.position-choices button small{display:block;color:#438167;font-size:.62rem}.position-hint,.position-extra{font-size:.72rem;color:#62746e;margin:8px 0 11px}.position-opening{display:flex;align-items:center;gap:9px;width:100%;min-height:43px;background:#fff;border:0;border-top:1px solid #e3ebe6;text-align:left;font:inherit}.position-opening span{flex:none;width:27px;color:#809089;font-size:.7rem;font-weight:750}.position-opening[aria-pressed=true] span{color:#006b43}.position-opening strong{font-size:.75rem}.position-save{width:100%;min-height:44px;margin-top:13px;background:#075b40;border:0;border-radius:5px;color:#fff;font:inherit;font-weight:750}.position-save:disabled{opacity:.45}.position-error{padding:10px;background:#fff0ed;color:#af342b;font-size:.77rem}
.position-publish{display:flex;align-items:center;gap:10px;padding:15px 0;border-top:1px solid #dce6e1}.position-publish button{min-height:40px;padding:0 13px;border:0;border-radius:5px;background:#075b40;color:#fff;font:inherit;font-size:.76rem;font-weight:750}.position-publish button:disabled{opacity:.45}.position-publish small,.position-publish a{font-size:.72rem;color:#587267}
.position-reset{min-height:42px;margin-top:5px;padding:0 10px;border:0;background:#fff;color:#0b6848;font:inherit;font-size:.76rem;font-weight:700}
